sys_script_include.script:
var WF_ChangeHRCABApprovalAjax = Class.create();
WF_ChangeHRCABApprovalAjax.prototype = Object.extendsObject(AbstractAjaxProcessor, {

    /**
     * Retrive Change Request Approvals.
     * 
     * @returns {string} returnValues - returns associated change request approvals.
     * 
     */
    getRecords: function() {
        var returnValues = [];
        var fromDT = this.getParameter('sysparm_from_dt') || '';
        var toDT = this.getParameter('sysparm_to_dt') || '';
        var encodedQuery = new global.WF_ChangeHRCABApprovalUtil().getApprovalsBetweenEncQuery(fromDT + "", toDT + "");
        if (!gs.nil(encodedQuery)) {
            var approvals = new GlideRecord('sysapproval_approver');
            approvals.addEncodedQuery(encodedQuery);
            approvals.query();
            while (approvals.next()) {
                //Push the value and display value to avoid any synchronous display value calls
                //when we populate the list collector on the catalog item
                returnValues.push({
                    "value": approvals.getUniqueValue(),
                    "displayValue": approvals.getDisplayValue()
                });
            }
        }
        return JSON.stringify(returnValues);
    },

    type: 'WF_ChangeHRCABApprovalAjax'
});
